data.query:
query Query($where: IntegrationWhereInput, $whereM: IntegrationModelWhereInput) {
  integration(where: $where, first:1) {
    edges { node {
      id
      name
      active
      configurationData
      integrationModels(where: $whereM, first:1, orderBy: {field: order, direction:asc}) {
        edges {node {
          id
          inboundFlowId
          name
          lastTransactionAt
          order
        }}
      }
    }}
  }
}

data.variablesTransform:
{
  "p": {
    "create": {
      "integrationId": $state.context.REQUEST.DATA.id,
      "message": $state.context.LOCAL.integration.name
        & " synchronization complete. "
        & $state.context.LOCAL.count
        & " integration models synchronized successfully.",
      "typeId": "Success",
      "global":true
    }
  }
}

{
  "p": {
    "create":{
      "integrationId": $state.context.REQUEST.DATA.id,
      "message": $state.context.LOCAL.integration.name
        & " sync failed. No active or subscribed models to sync.",
      "typeId": "Failure",
      "global":true
    }
  }
}

